package main

import (
	"context"
	"log"
	"os"

	clientv3 "go.etcd.io/etcd/client/v3"
	"go.etcd.io/etcd/client/v3/concurrency"
)

func main() {
	cli, err := clientv3.New(clientv3.Config{Endpoints: []string{"etcd-0:2379", "etcd-1:2379", "etcd-2:2379"}})
	if err != nil {
		log.Fatal(err)
	}
	defer cli.Close()

	// Session = a lease kept alive by heartbeats: if this pod dies,
	// the lease expires after 10 s and leadership is released.
	sess, err := concurrency.NewSession(cli, concurrency.WithTTL(10))
	if err != nil {
		log.Fatal(err)
	}
	defer sess.Close()

	e := concurrency.NewElection(sess, "/index-builder/leader")
	host, _ := os.Hostname()
	if err := e.Campaign(context.Background(), host); err != nil { // blocks until we win
		log.Fatal(err)
	}
	// Fencing token: the revision only grows, so storage can reject a stale leader.
	runIndexBuilds(sess.Done(), e.Rev()) // stop as soon as the lease is lost
}
